svg.script:

const STORAGE_KEY = 'svgAutoSyncData';

// Functie om scherm te updaten
function updateDisplay() {
  const val = localStorage.getItem(STORAGE_KEY) || "(leeg)";
  document.getElementById('statusLog').textContent = "Huidige LocalStorage: " + val;
}

// Handmatig opslaan vanuit het invoerveld in de SVG
function saveToLocal() {
  const inputVal = document.getElementById('localInput').value;
  if(inputVal.trim() !== "") {
    localStorage.setItem(STORAGE_KEY, inputVal);
    updateDisplay();
    document.getElementById('localInput').value = "";
  }
}

// 1. Luister naar inkomende berichten van de parent HTML en sla op in LocalStorage
window.addEventListener("message", function(event) {
  if (event.data && event.data.sender === "parent") {
    const incomingText = event.data.text;
    localStorage.setItem(STORAGE_KEY, incomingText);
    updateDisplay();
    document.getElementById('syncStatus').textContent = "Laatst ontvangen van parent en opgeslagen: " + incomingText;
  }
});

// 2. Stuur elke seconde de data vanuit LocalStorage naar de parent HTML
setInterval(function() {
  const currentData = localStorage.getItem(STORAGE_KEY);
  if (currentData) {
    window.parent.postMessage({
      sender: "svg-iframe",
      text: currentData
    }, "*");
  }
}, 1000);

// Initialiseer bij laden
window.addEventListener('DOMContentLoaded', updateDisplay);
